cs-0046 | agent:run-215 | tệp ×1 | Cập nhật hàm DrawLogo dùng dữ liệu ARGB8888

diff --git a/firmware/main.c b/firmware/main.c
index 8c8a003..bbe27ff 100644
--- a/firmware/main.c
+++ b/firmware/main.c
@@ -68,27 +68,31 @@ int main(void)
   }
 }

-static inline uint32_t rgb565_to_argb8888(uint16_t c)
-{
-  uint32_t r = (c >> 11) & 0x1F;
-  uint32_t g = (c >> 5) & 0x3F;
-  uint32_t b = c & 0x1F;
-
-  r = (r * 255 + 15) / 31;
-  g = (g * 255 + 31) / 63;
-  b = (b * 255 + 15) / 31;
-
-  return 0xFF000000UL | (r << 16) | (g << 8) | b;
-}
-
 static void DrawLogo(uint32_t x0, uint32_t y0)
 {
   for (uint32_t y = 0; y < LOGO_PTIT_HEIGHT; y++)
   {
     for (uint32_t x = 0; x < LOGO_PTIT_WIDTH; x++)
     {
-      uint16_t pixel565 = logo_ptit_data[y * LOGO_PTIT_WIDTH + x];
-      BSP_LCD_DrawPixel(x0 + x, y0 + y, rgb565_to_argb8888(pixel565));
+      uint32_t pixel = logo_ptit_data[y * LOGO_PTIT_WIDTH + x];
+      uint8_t a = (pixel >> 24) & 0xFF;
+      if (a > 0)
+      {
+        if (a == 255)
+        {
+          BSP_LCD_DrawPixel(x0 + x, y0 + y, pixel);
+        }
+        else
+        {
+          uint32_t r = (pixel >> 16) & 0xFF;
+          uint32_t g = (pixel >> 8) & 0xFF;
+          uint32_t b = pixel & 0xFF;
+          r = (r * a + 255 * (255 - a)) / 255;
+          g = (g * a + 255 * (255 - a)) / 255;
+          b = (b * a + 255 * (255 - a)) / 255;
+          BSP_LCD_DrawPixel(x0 + x, y0 + y, 0xFF000000UL | (r << 16) | (g << 8) | b);
+        }
+      }
     }
   }
 }

